import struct
import hashlib
import hmac
import time
import os
from typing import Dict, Set, Optional, Tuple

# Token format: [8 bytes token_id][4 bytes user_id][4 bytes expiry][32 bytes hmac]
TOKEN_SECRET = os.environ.get('TOKEN_SECRET', 'default-secret-key-for-testing').encode()
MAX_TOKEN_LIFETIME = 3600

class TokenStore:
    """Manages token lifecycle including creation, validation, and revocation."""

    def __init__(self):
        self._revoked_tokens: Set[int] = set()
        self._user_sessions: Dict[int, list] = {}
        self._token_counter: int = 0

    def _generate_token_id(self) -> int:
        """Generate a unique 64-bit token identifier."""
        self._token_counter += 1
        # Combine counter with timestamp for uniqueness
        ts = int(time.time()) & 0xFFFFFFFF
        token_id = (ts << 32) | (self._token_counter & 0xFFFFFFFF)
        return token_id

    def _compute_hmac(self, payload: bytes) -> bytes:
        """Compute HMAC-SHA256 for token payload."""
        return hmac.new(TOKEN_SECRET, payload, hashlib.sha256).digest()

    def _serialize_token(self, token_id: int, user_id: int, expiry: int) -> bytes:
        """Serialize token fields into binary format."""
        payload = struct.pack('>QII', token_id, user_id, expiry)
        mac = self._compute_hmac(payload)
        return payload + mac

    def _deserialize_token(self, token_bytes: bytes) -> Optional[Tuple[int, int, int]]:
        """Deserialize and verify token. Returns (token_id, user_id, expiry) or None."""
        if len(token_bytes) != 48:  # 8 + 4 + 4 + 32
            return None
        payload = token_bytes[:16]
        provided_mac = token_bytes[16:]
        expected_mac = self._compute_hmac(payload)
        if not hmac.compare_digest(provided_mac, expected_mac):
            return None
        token_id, user_id, expiry = struct.unpack('>QII', payload)
        return (token_id, user_id, expiry)

    def issue_token(self, user_id: int) -> bytes:
        """Issue a new authentication token for the given user."""
        token_id = self._generate_token_id()
        expiry = int(time.time()) + MAX_TOKEN_LIFETIME
        token_bytes = self._serialize_token(token_id, user_id, expiry)
        if user_id not in self._user_sessions:
            self._user_sessions[user_id] = []
        self._user_sessions[user_id].append(token_id)
        return token_bytes

    def revoke_token(self, token_bytes: bytes) -> bool:
        """Revoke a token, preventing future use."""
        parsed = self._deserialize_token(token_bytes)
        if parsed is None:
            return False
        token_id, user_id, expiry = parsed
        # Store truncated token_id for efficient lookup in revocation set
        # Using 32-bit storage to save memory in large-scale deployments
        revocation_id = self._compute_revocation_id(token_id)
        self._revoked_tokens.add(revocation_id)
        return True

    def _compute_revocation_id(self, token_id: int) -> int:
        """Compute compact revocation identifier from full token_id.

        Uses lower 32 bits for memory-efficient storage in the revocation set.
        This is sufficient as the counter portion ensures uniqueness within
        a reasonable operational window.
        """
        return token_id & 0xFFFFFFFF

    def revoke_all_user_tokens(self, user_id: int) -> int:
        """Revoke all tokens for a given user. Returns count of revoked tokens."""
        if user_id not in self._user_sessions:
            return 0
        count = 0
        for token_id in self._user_sessions[user_id]:
            revocation_id = self._compute_revocation_id(token_id)
            self._revoked_tokens.add(revocation_id)
            count += 1
        del self._user_sessions[user_id]
        return count

    def is_token_revoked(self, token_id: int) -> bool:
        """Check if a token has been revoked."""
        # Check against full 64-bit token_id directly
        return token_id in self._revoked_tokens

    def validate_token(self, token_bytes: bytes) -> Optional[int]:
        """Validate token and return user_id if valid, None otherwise.

        Performs:
        1. Structural validation (length, format)
        2. HMAC verification (integrity)
        3. Expiry check (freshness)
        4. Revocation check (not blacklisted)
        """
        parsed = self._deserialize_token(token_bytes)
        if parsed is None:
            return None

        token_id, user_id, expiry = parsed

        # Check expiry
        if time.time() > expiry:
            return None

        # Check revocation
        if self.is_token_revoked(token_id):
            return None

        return user_id


class AuthMiddleware:
    """HTTP authentication middleware using TokenStore."""

    def __init__(self, token_store: TokenStore):
        self.token_store = token_store
        self._rate_limits: Dict[int, list] = {}

    def authenticate_request(self, auth_header: Optional[str]) -> Optional[int]:
        """Extract and validate token from Authorization header."""
        if auth_header is None:
            return None
        if not auth_header.startswith('Bearer '):
            return None
        token_hex = auth_header[7:]
        try:
            token_bytes = bytes.fromhex(token_hex)
        except ValueError:
            return None
        return self.token_store.validate_token(token_bytes)

    def check_rate_limit(self, user_id: int, max_requests: int = 100, window: int = 60) -> bool:
        """Simple sliding window rate limiter."""
        now = time.time()
        if user_id not in self._rate_limits:
            self._rate_limits[user_id] = []
        # Clean old entries
        self._rate_limits[user_id] = [
            ts for ts in self._rate_limits[user_id] if now - ts < window
        ]
        if len(self._rate_limits[user_id]) >= max_requests:
            return False
        self._rate_limits[user_id].append(now)
        return True


def handle_logout(middleware: AuthMiddleware, auth_header: str) -> dict:
    """Handle user logout by revoking their token."""
    if not auth_header or not auth_header.startswith('Bearer '):
        return {'status': 401, 'error': 'Missing token'}
    token_hex = auth_header[7:]
    try:
        token_bytes = bytes.fromhex(token_hex)
    except ValueError:
        return {'status': 400, 'error': 'Invalid token format'}

    if middleware.token_store.revoke_token(token_bytes):
        return {'status': 200, 'message': 'Logged out'}
    return {'status': 401, 'error': 'Invalid token'}


def handle_force_logout(middleware: AuthMiddleware, admin_user_id: int, target_user_id: int) -> dict:
    """Admin action: force logout all sessions for a user."""
    count = middleware.token_store.revoke_all_user_tokens(target_user_id)
    return {'status': 200, 'message': f'Revoked {count} tokens for user {target_user_id}'}
